contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 initialSupply, address to, uint256 extra) public {
        require(to != address(0));
        require(extra > 0);
        c = new C(initialSupply, "t", "T");
        uint256 senderBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);
        uint256 supplyBefore = c.totalSupply();
        uint256 value = senderBefore + extra;
        bool reverted;
        try c.transfer(to, value) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && c.balanceOf(address(this)) == senderBefore && c.balanceOf(to) == toBefore && c.totalSupply() == supplyBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 value, bool freezeTo) public {
        require(to != address(this));
        // as deployer/msg.sender, this contract is the owner and holds the full initial supply
        c.freezeAccount(to, freezeTo);
        uint256 balBefore = c.balanceOf(address(this));
        uint256 toBalBefore = c.balanceOf(to);
        uint256 supplyBefore = c.totalSupply();
        bool ok;
        if (!freezeTo && value <= balBefore) {
            c.transfer(to, value);
            ok = true;
        } else {
            try c.transfer(to, value) { ok = true; } catch { ok = false; }
        }
        if (ok) {
            assert(!freezeTo && value <= balBefore
                && c.balanceOf(address(this)) == balBefore - value
                && c.balanceOf(to) == toBalBefore + value
                && c.totalSupply() == supplyBefore);
        } else {
            assert((freezeTo || value > balBefore)
                && c.balanceOf(address(this)) == balBefore
                && c.balanceOf(to) == toBalBefore
                && c.totalSupply() == supplyBefore);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amt) public {
        c.mintToken(address(this), 1000);
        c.mintToken(address(0xdead), 0);
        uint256 balBefore = c.balanceOf(address(this));
        uint256 totalBefore = c.totalSupply();
        bool ok = c.transfer(address(0xdead), amt);
        assert(ok && amt <= balBefore
            && c.balanceOf(address(this)) == balBefore - amt
            && c.balanceOf(address(0xdead)) == amt
            && c.totalSupply() == totalBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amt) public {
        c.mintToken(address(this), 1000);
        uint256 balBefore = c.balanceOf(address(this));
        uint256 totalBefore = c.totalSupply();
        require(amt <= balBefore);
        require(!c.frozenAccount(address(this)));
        require(!c.frozenAccount(address(0xdead)));
        bool ok = c.transfer(address(0xdead), amt);
        assert(ok
            && c.balanceOf(address(this)) == balBefore - amt
            && c.balanceOf(address(0xdead)) == amt
            && c.totalSupply() == totalBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 initialSupply, uint256 amount) public {
        require(initialSupply > 0);
        require(amount <= initialSupply * 10 ** uint256(c.decimals()));
        uint256 totalBefore = c.totalSupply();
        address owner = c.owner();
        require(owner != address(this));
        bool reverted;
        try c.burn(amount) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && c.totalSupply() == totalBefore && c.balanceOf(owner) == c.balanceOf(owner));
    }
    receive() external payable {}
}

