contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target) public {
        bool before;
        try c.frozenAccount(target) returns (bool v) { before = v; } catch { before = false; }
        bool reverted;
        try c.freezeAccount(target, !before) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.frozenAccount(target) == before);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 mintAmount, uint256 transferAmount, uint256 burnAmount) public {
        require(target != address(0));
        c.mintToken(target, mintAmount);
        if (c.balanceOf(address(this)) >= transferAmount) {
            c.transfer(target, transferAmount);
        }
        bool burnReverted;
        try c.burn(burnAmount) { burnReverted = false; } catch { burnReverted = true; }
        if (!burnReverted) {
            require(c.balanceOf(address(this)) >= burnAmount);
        }
        assert(c.totalSupply() == c.balanceOf(address(this)) + c.balanceOf(target));
    }
    receive() external payable {}
}

