contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 amount) public {
        require(to != address(0));
        // fund the test contract (which is the owner of c and its caller)
        c.mintToken(address(this), amount);
        // freeze then unfreeze the test contract's own account
        c.freezeAccount(address(this), true);
        c.freezeAccount(address(this), false);
        uint256 before = c.balanceOf(address(this));
        require(before >= amount);
        require(!c.frozenAccount(address(this)));
        bool success = c.transfer(to, amount);
        assert(
            success &&
            c.balanceOf(to) == amount &&
            c.balanceOf(address(this)) + amount == before &&
            c.totalSupply() == before
        );
    }
